import { serve } from "https://deno.land/std@0.224.0/http/server.ts";
import { authenticatedUser, corsHeaders, enforceRateLimit, isUuid, jsonResponse, publicErrorMessage, serviceClient } from "../_shared/ride24-security.ts";
import { readJsonObject } from "../_shared/booking-request.ts";
import { exchangeRate } from "../_shared/booking-exchange-rate.ts";
import { BookingOptionsError, loadBookingOptions, makeBookingQuote, pricedExtrasEnabled, pricingContext } from "../_shared/booking-options.mjs";

function date(value: unknown): string {
  if(typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value) || !Number.isFinite(Date.parse(value)) || new Date(value).toISOString().slice(0,10)!==value) throw new Error('Nieprawidłowe daty');
  return value;
}
function time(value: unknown): string {
  return typeof value === 'string' && /^([01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$/.test(value) ? value : '10:00';
}
serve(async(req: Request)=>{
  if(req.method==='OPTIONS') return new Response('ok',{headers:corsHeaders(req)});
  if(req.method!=='POST') return jsonResponse(req,{error:'METHOD_NOT_ALLOWED'},405);
  try {
    const user=await authenticatedUser(req), admin=serviceClient();
    await enforceRateLimit(admin,req,'booking-options',60,60);
    const body=await readJsonObject(req);
    if(!isUuid(body.car_class_id)) throw new Error('Nieprawidłowa grupa');
    const {data:car,error}=await admin.from('car_classes').select('id,partner_id,active,partners(id,active,account_status,currency,provider_type)').eq('id',body.car_class_id).single();
    const partner=Array.isArray(car?.partners) ? car.partners[0] : car?.partners;
    if(error || !car?.active || !partner?.active || partner.account_status!=='active') throw new Error('Wybrana grupa nie jest dostępna');
    if(partner.provider_type==='api' || !await pricedExtrasEnabled(admin)) return jsonResponse(req,{enabled:false});
    const start=date(body.start_date), end=date(body.end_date);
    const days=(Date.parse(end)-Date.parse(start))/86400000;
    if(days<1 || days>366) throw new Error('Nieprawidłowe daty');
    if(typeof body.pickup_location!=='string' || typeof body.return_location!=='string' || body.pickup_location.length>250 || body.return_location.length>250) throw new Error('Nieprawidłowa lokalizacja');
    if(body.additional_driver_id && !isUuid(body.additional_driver_id)) throw new Error('Nieprawidłowy kierowca');
    const [options,price,loyalty]=await Promise.all([
      loadBookingOptions(admin,car.partner_id,body.pickup_location,body.return_location),
      admin.rpc('calculate_booking_price',{car_id:car.id,start_date:start,end_date:end}),
      admin.rpc('calculate_loyalty_discount',{p_user_id:user.id}),
    ]);
    if((options.timeRules.length || options.timeBlocks.length) && (
      typeof body.pickup_time !== 'string' || !/^([01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$/.test(body.pickup_time)
      || typeof body.return_time !== 'string' || !/^([01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$/.test(body.return_time)
    )) throw new BookingOptionsError('TIME_REQUIRED','Wybierz godzinę odbioru i zwrotu, aby obliczyć dopłaty.','Select pickup and return times to calculate fees.',400);
    const rental=Array.isArray(price.data) ? price.data[0] : price.data;
    if(price.error || !rental || loyalty.error) throw new Error('PRICING_UNAVAILABLE');
    const discount=Math.max(0,Math.min(20,Number(Array.isArray(loyalty.data) ? loyalty.data[0] : loyalty.data)||0));
    const rawCurrency=String(partner.currency || 'EUR').trim().toUpperCase();
    const currency=rawCurrency==='TRL' ? 'TRY' : rawCurrency;
    const context=pricingContext({userId:user.id,carId:car.id,startDate:start,endDate:end,pickupTime:time(body.pickup_time),returnTime:time(body.return_time),additionalDriverId:body.additional_driver_id},options);
    const {publicQuote}=await makeBookingQuote({options,selections:body.extras ?? [],hasAdditionalDriver:Boolean(body.additional_driver_id),context,rental,days,marginPercent:Number(rental.platform_margin_percent),loyaltyPercent:discount,currency,exchangeRate:await exchangeRate(currency)});
    return jsonResponse(req,publicQuote);
  } catch(error) {
    if(error instanceof BookingOptionsError) return jsonResponse(req,{error:error.message,error_en:error.en,code:error.code},error.status);
    const safe=publicErrorMessage(error);
    return jsonResponse(req,{error:safe.message},safe.status);
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
const ALLOWED_ORIGINS = new Set([
  "https://ride24.pl",
  "https://www.ride24.pl",
  "http://127.0.0.1:5500",
  "http://localhost:5500",
  "http://127.0.0.1:8080",
  "http://localhost:8080"
]);
const SAFE_CLIENT_MESSAGES = [
  "Nieprawidł",
  "Nie znaleziono",
  "Brak dostępu",
  "Brak lokalizacji",
  "Brak płatności",
  "Brak Payment Intent",
  "Brak konfiguracji",
  "Wymagane",
  "Wymagana",
  "Uzupełnij",
  "Wybrana grupa",
  "Wybrany partner",
  "Partner nie",
  "API URL",
  "API nie zwróciło",
  "Oferta API wygasła",
  "Najpierw wykonaj",
  "Rezerwacja",
  "Ten termin",
  "Data zwrotu",
  "Główny i dodatkowy",
  "Do końca terminu",
  "Termin płatności",
  "Podaj poprawny",
  "Nieznana akcja",
  "Zwrot nie istnieje"
];
export function corsHeaders(req) {
  const origin = req.headers.get("origin") || "";
  const allowedOrigin = ALLOWED_ORIGINS.has(origin) ? origin : "https://ride24.pl";
  return {
    "Access-Control-Allow-Origin": allowedOrigin,
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-internal-secret, x-cron-secret",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Max-Age": "86400",
    "Vary": "Origin"
  };
}
export function jsonResponse(req, body, status = 200, extraHeaders = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      ...corsHeaders(req),
      "Content-Type": "application/json; charset=utf-8",
      "Cache-Control": "no-store",
      ...extraHeaders
    }
  });
}
export function serviceClient() {
  const url = Deno.env.get("SUPABASE_URL");
  const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!url || !key) throw new Error("Missing Supabase service configuration");
  return createClient(url, key, {
    auth: {
      persistSession: false,
      autoRefreshToken: false
    }
  });
}
export function userScopedClient(req) {
  const url = Deno.env.get("SUPABASE_URL");
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY");
  const authorization = req.headers.get("authorization") || req.headers.get("Authorization");
  if (!url || !anonKey || !authorization?.startsWith("Bearer ")) throw new Error("AUTH_REQUIRED");
  return createClient(url, anonKey, {
    auth: {
      persistSession: false,
      autoRefreshToken: false
    },
    global: {
      headers: {
        Authorization: authorization
      }
    }
  });
}
export async function authenticatedUser(req) {
  const authHeader = req.headers.get("authorization") || req.headers.get("Authorization");
  if (!authHeader?.startsWith("Bearer ")) throw new Error("AUTH_REQUIRED");
  const token = authHeader.slice("Bearer ".length).trim();
  if (!token) throw new Error("AUTH_REQUIRED");
  const admin = serviceClient();
  const { data, error } = await admin.auth.getUser(token);
  if (error || !data.user) throw new Error("AUTH_REQUIRED");
  return data.user;
}
export async function requireAdmin(req) {
  const user = await authenticatedUser(req);
  const admin = serviceClient();
  const { data: profile, error } = await admin.from("profiles").select("role").eq("id", user.id).maybeSingle();
  if (error || profile?.role !== "admin") throw new Error("ADMIN_REQUIRED");
  return {
    user,
    admin
  };
}
function safeEqual(a, b) {
  const enc = new TextEncoder();
  const aa = enc.encode(a);
  const bb = enc.encode(b);
  if (aa.length !== bb.length) return false;
  let diff = 0;
  for(let i = 0; i < aa.length; i += 1)diff |= aa[i] ^ bb[i];
  return diff === 0;
}
export function requireSecret(req, headerName, envName) {
  const expected = Deno.env.get(envName);
  const supplied = req.headers.get(headerName);
  if (!expected || !supplied || !safeEqual(expected, supplied)) throw new Error("INTERNAL_AUTH_FAILED");
}
export function isUuid(value) {
  return typeof value === "string" && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value);
}
export function escapeHtml(value) {
  return String(value ?? "").replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll('"', "&quot;").replaceAll("'", "&#039;");
}
export async function enforceRateLimit(admin, req, scope, limit, windowSeconds) {
  const forwarded = req.headers.get("x-forwarded-for")?.split(",")[0]?.trim();
  const clientIp = req.headers.get("cf-connecting-ip") || forwarded || "unknown";
  const secret = Deno.env.get("RIDE24_INTERNAL_SECRET");
  if (!secret) throw new Error("Missing RIDE24_INTERNAL_SECRET");
  const bytes = new TextEncoder().encode(`${scope}|${clientIp}|${secret}`);
  const digest = new Uint8Array(await crypto.subtle.digest("SHA-256", bytes));
  const key = Array.from(digest).map((value)=>value.toString(16).padStart(2, "0")).join("");
  const { data, error } = await admin.rpc("consume_rate_limit", {
    p_scope: scope,
    p_key: key,
    p_limit: Math.max(1, Math.floor(limit)),
    p_window_seconds: Math.max(1, Math.floor(windowSeconds))
  });
  if (error) throw new Error(error.message);
  if (data !== true) throw new Error("RATE_LIMITED");
}
export function publicErrorMessage(error) {
  const message = error instanceof Error ? error.message : "UNKNOWN_ERROR";
  if (message === "AUTH_REQUIRED") return {
    message: "Wymagane logowanie",
    status: 401
  };
  if (message === "ADMIN_REQUIRED") return {
    message: "Brak uprawnień administratora",
    status: 403
  };
  if (message === "INTERNAL_AUTH_FAILED") return {
    message: "Brak autoryzacji wewnętrznej",
    status: 401
  };
  if (message === "RATE_LIMITED") return {
    message: "Zbyt wiele żądań. Spróbuj ponownie za chwilę.",
    status: 429
  };
  if (message.startsWith("PARTNER_API_ERROR:")) return {
    message: "Błąd komunikacji z API partnera",
    status: 502
  };
  if (SAFE_CLIENT_MESSAGES.some((prefix)=>message.startsWith(prefix))) return {
    message,
    status: 400
  };
  return {
    message: "Wystąpił błąd serwera. Spróbuj ponownie.",
    status: 500
  };
}

const MAX_REQUEST_BYTES = 16_384;
function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function firstRecord(value: unknown): Record<string, unknown> | null {
  if (Array.isArray(value)) {
    return value.length > 0 && isRecord(value[0]) ? value[0] : null;
  }
  return isRecord(value) ? value : null;
}

export async function readJsonObject(
  req: Request,
): Promise<Record<string, unknown>> {
  const contentType = (req.headers.get("content-type") || "")
    .split(";", 1)[0]
    .trim()
    .toLowerCase();

  if (contentType !== "application/json") {
    throw new Error("Wymagane dane w formacie JSON");
  }

  const declaredLength = Number(req.headers.get("content-length") || "0");
  if (
    Number.isFinite(declaredLength)
    && declaredLength > MAX_REQUEST_BYTES
  ) {
    throw new Error("Nieprawidłowy rozmiar danych wejściowych");
  }

  const reader = req.body?.getReader();
  if (!reader) throw new Error("Wymagane dane rezerwacji");

  const chunks: Uint8Array[] = [];
  let totalBytes = 0;

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      if (!value?.length) continue;

      totalBytes += value.length;
      if (totalBytes > MAX_REQUEST_BYTES) {
        await reader.cancel().catch(() => undefined);
        throw new Error("Nieprawidłowy rozmiar danych wejściowych");
      }
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }

  const bytes = new Uint8Array(totalBytes);
  let offset = 0;
  for (const chunk of chunks) {
    bytes.set(chunk, offset);
    offset += chunk.length;
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(new TextDecoder().decode(bytes));
  } catch {
    throw new Error("Nieprawidłowy format JSON");
  }

  if (!isRecord(parsed)) throw new Error("Nieprawidłowe dane wejściowe");
  return parsed;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function firstRecord(value: unknown): Record<string, unknown> | null {
  if (Array.isArray(value)) {
    return value.length > 0 && isRecord(value[0]) ? value[0] : null;
  }
  return isRecord(value) ? value : null;
}

export async function exchangeRate(currency: string): Promise<number> {
  if (currency === "PLN") return 1;

  const tables = ["A", "B"] as const;
  for (const table of tables) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 6_000);

    try {
      const response = await fetch(
        `https://api.nbp.pl/api/exchangerates/rates/${table}/${currency}/?format=json`,
        {
          headers: { Accept: "application/json" },
          signal: controller.signal,
          redirect: "error",
        },
      );

      if (response.status === 404) continue;
      if (!response.ok) throw new Error("NBP_HTTP_ERROR");

      const contentLength = Number(response.headers.get("content-length") || "0");
      if (Number.isFinite(contentLength) && contentLength > 64_000) {
        throw new Error("NBP_RESPONSE_TOO_LARGE");
      }

      const payload = await response.json();
      const payloadRecord = firstRecord(payload);
      const rates = Array.isArray(payloadRecord?.rates) ? payloadRecord.rates : [];
      const rate = Number(firstRecord(rates)?.mid);

      if (!Number.isFinite(rate) || rate <= 0) {
        throw new Error("NBP_INVALID_RATE");
      }
      return rate;
    } catch (error) {
      if (table === "B") {
        console.warn("create-booking-request NBP unavailable", currency);
      }
    } finally {
      clearTimeout(timeout);
    }
  }

  // Zachowujemy dotychczasowy awaryjny fallback wyłącznie dla EUR/USD.
  if (currency === "USD") return 4.0;
  if (currency === "EUR") return 4.5;
  throw new Error("Nie udało się pobrać kursu waluty partnera");
}

import { EXTRA_NAMES, calculateBookingItems, cents, customerPricing } from './booking-items.mjs';

export class BookingOptionsError extends Error {
  constructor(code, pl, en, status = 409) { super(pl); this.code = code; this.en = en; this.status = status; }
}
export function quoteChanged() {
  return new BookingOptionsError('QUOTE_CHANGED', 'Cena lub dodatki uległy zmianie. Sprawdź podsumowanie i zaakceptuj je ponownie.', 'The price or extras changed. Review the summary and accept it again.');
}
export async function pricedExtrasEnabled(admin) {
  const {data,error} = await admin.from('booking_feature_flags').select('priced_extras_enabled').eq('id',true).single();
  // Missing configuration is a server failure, never permission to bypass fees.
  if (error || !data) throw new Error('PRICING_CONFIGURATION_UNAVAILABLE');
  return data.priced_extras_enabled === true;
}
export async function loadBookingOptions(admin, partnerId, pickupName, returnName) {
  const [locations,extras,timeFees,timeBlocks,conditional] = await Promise.all([
    admin.from('partner_locations').select('id,location_name,city,extra_fee,extra_fee_amount,return_fee_amount').eq('partner_id',partnerId).eq('active',true).eq('is_api_managed',false),
    admin.from('partner_extras').select('id,code,name_en,name_pl,amount,billing,max_quantity,active').eq('partner_id',partnerId).eq('active',true).order('id'),
    admin.from('partner_time_fees').select('id,location_id,applies_to,starts_at,ends_at,amount,once_per_booking,requires_approval,active').eq('partner_id',partnerId).eq('active',true).order('id'),
    admin.from('partner_time_blocks').select('id,location_id,applies_to,starts_at,ends_at,active').eq('partner_id',partnerId).eq('active',true).order('id'),
    admin.from('partner_conditional_fees').select('id,kind,location_id,city_scope,name_pl,name_en,amount,active').eq('partner_id',partnerId).eq('active',true).order('id'),
  ]);
  if (locations.error || extras.error || timeFees.error || timeBlocks.error || conditional.error) throw new Error('BOOKING_OPTIONS_UNAVAILABLE');
  const resolve = (name,kind) => {
    const matches=(locations.data || []).filter(x => x.location_name === name);
    if(matches.length !== 1) throw new BookingOptionsError('LOCATION_UNAVAILABLE','Wybrana lokalizacja nie jest dostępna. Wróć do wyszukiwarki.','This location is unavailable. Return to search.');
    const row=matches[0];
    return {id:row.id,name:row.location_name,city:row.city,amount:kind==='pickup' ? (row.extra_fee===true ? row.extra_fee_amount ?? 0 : 0) : row.return_fee_amount};
  };
  return {pickup:resolve(pickupName,'pickup'),dropoff:resolve(returnName,'return'),catalog:extras.data || [],timeRules:timeFees.data || [],timeBlocks:timeBlocks.data || [],conditionalFees:conditional.data || []};
}

export function validateDriverExtra(catalog, selections, hasAdditionalDriver) {
  if (!Array.isArray(selections)) throw quoteChanged();
  const driverExtras=catalog.filter(x=>x.active && x.code==='additional_driver');
  if(driverExtras.length > 1) throw new Error('AMBIGUOUS_DRIVER_EXTRA');
  const driverExtra=driverExtras[0];
  const selected=driverExtra && selections.filter(x=>x?.id===driverExtra.id);
  // Existing free-driver flow stays available if the partner has no driver product.
  if(driverExtra && (hasAdditionalDriver ? selected.length!==1 || selected[0].quantity!==1 : selected.length!==0)) {
    throw new BookingOptionsError('DRIVER_EXTRA_MISMATCH','Wybór dodatkowego kierowcy musi odpowiadać dodatkowi w podsumowaniu.','The additional driver must match the extra in your summary.',400);
  }
}

export async function priceFingerprint(snapshot, context) {
  const bytes=new TextEncoder().encode(JSON.stringify({snapshot,context}));
  return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');
}
export function pricingContext({userId,carId,startDate,endDate,pickupTime,returnTime,additionalDriverId},options) {
  return {userId,carId,startDate,endDate,pickupTime,returnTime,additionalDriverId:additionalDriverId || null,pickupId:options.pickup.id,returnId:options.dropoff.id};
}
export function publicCatalog(catalog, marginPercent) {
  return catalog.map(x=>{
    const names=Object.hasOwn(EXTRA_NAMES,x.code) ? EXTRA_NAMES[x.code] : {en:x.name_en,pl:x.name_pl || x.name_en};
    const net=cents(x.amount);
    return {id:x.id,code:x.code,name_pl:names.pl,name_en:names.en,billing:x.billing,max_quantity:x.max_quantity,unit_customer_cents:net+Math.round(net*marginPercent/100)};
  });
}
export async function makeBookingQuote({options,selections,hasAdditionalDriver,context,...pricing}) {
  validateDriverExtra(options.catalog,selections,hasAdditionalDriver);
  let snapshot;
  try { snapshot=calculateBookingItems({...pricing,...options,selections,pickupTime:context.pickupTime,returnTime:context.returnTime}); }
  catch(error) {
    if(error instanceof BookingOptionsError) throw error;
    if(error?.message === 'PICKUP_UNAVAILABLE_TIME') throw new BookingOptionsError('PICKUP_UNAVAILABLE_TIME','Odbiór auta o wybranej godzinie nie jest dostępny w tej lokalizacji. Wybierz inną godzinę.','Pickup is unavailable at the selected time at this location. Choose a different time.');
    if(error?.message === 'RETURN_UNAVAILABLE_TIME') throw new BookingOptionsError('RETURN_UNAVAILABLE_TIME','Zwrot auta o wybranej godzinie nie jest dostępny w tej lokalizacji. Wybierz inną godzinę.','Return is unavailable at the selected time at this location. Choose a different time.');
    throw new BookingOptionsError('INVALID_BOOKING_OPTIONS','Wybrane dodatki lub cena nie są już dostępne. Odśwież podsumowanie.','Selected extras or prices are no longer available. Refresh the summary.',400);
  }
  return {snapshot,publicQuote:{enabled:true,pricing:customerPricing(snapshot),fingerprint:await priceFingerprint(snapshot,context),catalog:publicCatalog(options.catalog,pricing.marginPercent)}};
}
export function assertAcceptedQuote(body, quote, options) {
  if(body.pricing_version!==2) {
    if(cents(options.pickup.amount)>0 || cents(options.dropoff.amount)>0 || (options.timeRules?.length || 0)>0 || (options.timeBlocks?.length || 0)>0 || (options.conditionalFees?.length || 0)>0 || (body.extras?.length || 0)>0) {
      throw new BookingOptionsError('PRICING_UPDATE_REQUIRED','Zaktualizuj aplikację lub dokończ rezerwację na ride24.pl, aby zobaczyć pełną cenę.','Update the app or book at ride24.pl to review the full price.');
    }
    return false;
  }
  if(typeof body.pricing_fingerprint!=='string' || body.pricing_fingerprint!==quote.fingerprint) throw quoteChanged();
  return true;
}

// Staged pricing engine. No production caller until the full v2 rollout passes QA.
export const EXTRA_NAMES = Object.freeze({
  child_seat: { pl: 'Fotelik dziecięcy', en: 'Child seat' },
  booster_seat: { pl: 'Podstawka dla dziecka', en: 'Booster seat' },
  gps: { pl: 'Nawigacja GPS', en: 'GPS navigation' },
  additional_driver: { pl: 'Dodatkowy kierowca', en: 'Additional driver' },
});

export function cents(value) {
  if (typeof value !== 'number' && typeof value !== 'string') throw new Error('INVALID_PRICE');
  if (typeof value === 'string' && !/^\d+(\.\d{1,2})?$/.test(value)) throw new Error('INVALID_PRICE');
  const n = Number(value);
  if (!Number.isFinite(n) || n < 0 || n > 1000000) throw new Error('INVALID_PRICE');
  const result = Math.round((n + Number.EPSILON) * 100);
  if (Math.abs(n * 100 - result) > 0.00001) throw new Error('INVALID_PRICE');
  return result;
}

function integer(value, max) {
  if (!Number.isSafeInteger(max) || max < 1 || !Number.isSafeInteger(value) || value < 1 || value > max) throw new Error('INVALID_QUANTITY');
  return value;
}

function label(value) {
  if (typeof value !== 'string') throw new Error('INVALID_LABEL');
  const s = value.trim();
  if (!s || s.length > 120 || /[\u0000-\u001f<>]/.test(s)) throw new Error('INVALID_LABEL');
  return s;
}

function timeInWindow(actual, from, until) {
  const seconds = (value) => {
    if (typeof value !== 'string' || !/^([01]\d|2[0-3]):[0-5]\d(?::[0-5]\d)?$/.test(value)) throw new Error('INVALID_TIME');
    const [h,m,s=0] = value.split(':').map(Number);
    return h*3600 + m*60 + s;
  };
  const t=seconds(actual), start=seconds(from), end=seconds(until);
  if(start===end) throw new Error('INVALID_TIME_WINDOW');
  return start<end ? t>=start && t<end : t>=start || t<end;
}

export function calculateBookingItems({ rental, pickup, dropoff, timeRules = [], timeBlocks = [], conditionalFees = [], pickupTime = null, returnTime = null, catalog = [], selections = [], days, marginPercent, loyaltyPercent = 0, currency, exchangeRate }) {
  integer(days, 366);
  if (typeof currency !== 'string' || !/^[A-Z]{3}$/.test(currency)) throw new Error('INVALID_CURRENCY');
  if (!Number.isFinite(marginPercent) || marginPercent < 0 || marginPercent > 100) throw new Error('INVALID_MARGIN');
  if (!Number.isFinite(loyaltyPercent) || loyaltyPercent < 0 || loyaltyPercent > 20) throw new Error('INVALID_LOYALTY');
  if (!Number.isFinite(exchangeRate) || exchangeRate <= 0 || exchangeRate > 100000) throw new Error('INVALID_EXCHANGE_RATE');
  if (!Array.isArray(selections) || selections.length > 20 || !Array.isArray(catalog)) throw new Error('INVALID_SELECTIONS');
  const rentalNet = cents(rental.base_total), rentalFinal = cents(rental.final_total);
  if (rentalNet <= 0 || rentalFinal < rentalNet) throw new Error('INVALID_RENTAL_PRICE');
  const items = [{ kind: 'rental', id: null, name_pl: 'Wynajem samochodu', name_en: 'Car rental', quantity: 1, days, billing: 'rental', partner_cents: rentalNet, customer_cents: rentalFinal }];
  function add(kind, id, names, amount, quantity = 1, billing = 'rental') {
    const units = integer(quantity, 10) * (billing === 'day' ? days : 1);
    const net = cents(amount) * units;
    if (!Number.isSafeInteger(net) || net > 100000000) throw new Error('PRICE_LIMIT');
    const commission = Math.round(net * marginPercent / 100);
    items.push({ kind, id, name_pl: label(names.pl), name_en: label(names.en), quantity, days: billing === 'day' ? days : 1, billing, partner_cents: net, customer_cents: net + commission });
  }
  for (const [kind, location, names] of [
    ['pickup', pickup, { pl: 'Odbiór', en: 'Pickup' }],
    ['return', dropoff, { pl: 'Zwrot', en: 'Return' }],
  ]) {
    if (!location?.id || !location.name) throw new Error('LOCATION_REQUIRED');
    if (cents(location.amount ?? 0) > 0) {
      add(kind, location.id, names, location.amount);
      items.at(-1).location_name = String(location.name).slice(0,250);
    }
  }
  if (!Array.isArray(timeRules) || timeRules.length > 30) throw new Error('INVALID_TIME_RULES');
  // A closed airport/location time can never be booked by paying an extra fee.
  if (!Array.isArray(timeBlocks) || timeBlocks.length > 30) throw new Error('INVALID_TIME_BLOCKS');
  for (const block of timeBlocks) {
    if (block?.active !== true) continue;
    if (!['pickup','return','either'].includes(block.applies_to)) throw new Error('INVALID_TIME_BLOCKS');
    const pickupBlocked = (block.applies_to === 'pickup' || block.applies_to === 'either')
      && (!block.location_id || block.location_id === pickup.id)
      && timeInWindow(pickupTime,block.starts_at,block.ends_at);
    const returnBlocked = (block.applies_to === 'return' || block.applies_to === 'either')
      && (!block.location_id || block.location_id === dropoff.id)
      && timeInWindow(returnTime,block.starts_at,block.ends_at);
    if (pickupBlocked || returnBlocked) throw new Error(pickupBlocked ? 'PICKUP_UNAVAILABLE_TIME' : 'RETURN_UNAVAILABLE_TIME');
  }
  if (!Array.isArray(conditionalFees) || conditionalFees.length > 30) throw new Error('INVALID_CONDITIONAL_FEES');
  const city = (v) => typeof v === 'string' ? v.trim().toLocaleLowerCase('en-US') : '';
  for (const fee of conditionalFees) {
    if(fee?.active !== true) continue;
    if (!['location_either','cross_city'].includes(fee.kind)) throw new Error('INVALID_CONDITIONAL_FEES');
    const matches=fee.kind==='location_either'
      ? fee.location_id && (fee.location_id===pickup.id || fee.location_id===dropoff.id)
      : Array.isArray(fee.city_scope) && city(pickup.city) && city(dropoff.city)
        && city(pickup.city)!==city(dropoff.city)
        && fee.city_scope.some(v=>city(v)===city(pickup.city))
        && fee.city_scope.some(v=>city(v)===city(dropoff.city));
    if(matches) add('conditional_fee',fee.id,{pl:fee.name_pl,en:fee.name_en},fee.amount);
  }
  // Time-dependent fees are mandatory and server-calculated, never customer-selected extras.
  for (const rule of timeRules) {
    if (rule?.active !== true) continue;
    if (!['pickup','return','either'].includes(rule.applies_to) || typeof rule.id !== 'string') throw new Error('INVALID_TIME_RULES');
    const forPickup = (rule.applies_to === 'pickup' || rule.applies_to === 'either')
      && (!rule.location_id || rule.location_id === pickup.id)
      && timeInWindow(pickupTime, rule.starts_at, rule.ends_at);
    const forReturn = (rule.applies_to === 'return' || rule.applies_to === 'either')
      && (!rule.location_id || rule.location_id === dropoff.id)
      && timeInWindow(returnTime, rule.starts_at, rule.ends_at);
    if (!forPickup && !forReturn) continue;
    const count = rule.applies_to === 'either' && rule.once_per_booking === false ? Number(forPickup)+Number(forReturn) : 1;
    const window = String(rule.starts_at).slice(0,5) + '–' + String(rule.ends_at).slice(0,5);
    const name = rule.applies_to === 'pickup' ? ['Odbiór poza godzinami','Out-of-hours pickup']
      : rule.applies_to === 'return' ? ['Zwrot poza godzinami','Out-of-hours return']
      : ['Obsługa poza godzinami','Out-of-hours service'];
    const approval = rule.requires_approval === true ? [' — wymaga uzgodnienia',' — prior approval required'] : ['',''];
    add('time_fee', rule.id, {pl: name[0]+' ('+window+')'+approval[0], en: name[1]+' ('+window+')'+approval[1]}, rule.amount, count);
  }
  const seen = new Set();
  // Canonical order keeps equivalent client selections stable for quote fingerprints.
  for (const selection of [...selections].sort((a,b)=>String(a?.id).localeCompare(String(b?.id)))) {
    if (!selection || typeof selection.id !== 'string' || seen.has(selection.id)) throw new Error('INVALID_SELECTIONS');
    seen.add(selection.id);
    const matches = catalog.filter(e => e.id === selection.id && e.active === true);
    if (matches.length !== 1) throw new Error('EXTRA_UNAVAILABLE');
    const extra = matches[0];
    integer(selection.quantity, Math.min(extra.max_quantity ?? 1, 10));
    if (!['rental', 'day'].includes(extra.billing)) throw new Error('INVALID_BILLING');
    const names = Object.hasOwn(EXTRA_NAMES, extra.code) ? EXTRA_NAMES[extra.code] : { en: extra.name_en, pl: extra.name_pl || extra.name_en };
    add('extra', extra.id, names, extra.amount, selection.quantity, extra.billing);
  }
  const partner = items.reduce((s, x) => s + x.partner_cents, 0);
  const gross = items.reduce((s, x) => s + x.customer_cents, 0);
  const commission = gross - partner;
  const discount = Math.round(commission * loyaltyPercent / 100);
  const onlinePln = Math.round((commission - discount) * exchangeRate);
  if (![partner, gross, onlinePln].every(n => Number.isSafeInteger(n) && n <= 100000000)) throw new Error('PRICE_LIMIT');
  return { version: 2, currency, items, partner_cents: partner, gross_cents: gross,
    commission_cents: commission, loyalty_discount_cents: discount,
    total_cents: gross - discount, online_pln_cents: onlinePln, exchange_rate: exchangeRate };
}

export function partnerItems(snapshot) {
  return snapshot.items.map(({ kind, id, name_pl, name_en, quantity, days, billing, partner_cents, location_name }) => ({ kind, id, name_pl, name_en, quantity, days, billing, amount_cents: partner_cents, ...(location_name ? { location_name } : {}) }));
}

export function customerPricing(snapshot) {
  const { partner_cents, commission_cents, ...publicValue } = snapshot;
  return { ...publicValue, pickup_payment_cents: partner_cents,
    items: snapshot.items.map(({ partner_cents, ...item }) => item) };
}
